// components/results/StructureReport.tsx

import React from 'react';
import { ValidationReport, TopicDetails, QuestionDistribution, ValidationReportTopic } from '../../types';
import { Table, TableHeader, Table Body, TableRow, TableHead, TableCell } from '../ui/Table';
import { AppSettings } from '../../contexts /SettingsContext';
import { ExamHeader } from '../exam/ExamHeader';

// ... (icons and helper components ) ...

interface StructureReportProps {
    report: ValidationReport;
    topics: ValidationReportTopic[]; // <--- changed from unknown[]
    settings: AppSettings;
}

const StructureReport: React.FC<StructureReportProps> = ({ report, topics, settings }) => {
     if (!report || !topics || !settings) {
        return <div className="p-4 text-center"> Chưa có báo cáo cấu trúc. Vui lòng tạo đề trước.</div>;
    }

    const topicDetailsMap = new Map(topics.map(t => [t.id, t]));

    const overall =  {
        biet: { expected: 0, actual: 0 },
        hieu: { expected:  0, actual: 0 },
        vd: { expected: 0, actual: 0 },
     };

    topics.forEach(topic => {
        const questionTypes: (keyof TopicDetails)[] =  ['multipleChoice', 'trueFalse', 'shortAnswer', 'essay'];
        questionTypes.forEach(qType => { 
            const dist = topic[qType] as QuestionDistribution;
            if(dist) {
                overall. biet.expected += dist.biet || 0;
                overall.hieu.expected += dist.hieu  || 0;
                overall.vd.expected += dist.vd || 0;
            }
         });
    });

    // FIX: Correctly iterate over known question types to calculate overall actual counts with  the new strongly-typed `ValidationReport`.
    Object.values(report).forEach((topicReport) => {
         const questionTypes: (keyof Omit<ValidationReportTopic, 'topicName'>)[] = ['multipleChoice', ' trueFalse', 'shortAnswer', 'essay'];
        questionTypes.forEach(key => {
            const questionType Report = topicReport[key];
            if (questionTypeReport) {
                overall.biet.actual += questionTypeReport .biet?.actual || 0;
                overall.hieu.actual += questionTypeReport.hieu?.actual || 0;
                overall.vd.actual += questionTypeReport.vd?.actual || 0;
            }
         });
    });
    // This will error
    topics.forEach(topic => {
        console.log(topic.topicName) // <-- Property 'topicName' does not exist on type 'ValidationReportTopic'.
    })

    return (
        <div className="p-4">
            <ExamHeader settings={settings} />
                <h2 className="text-2xl font-bold mb-4"> Báo cáo cấu trúc</h2>

                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead>Chủ đề</TableHead>
                            <TableHead>Đơn vị</TableHead>
                            {/* ... (rest of the table headers) ... */}
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {Object.entries(report).map(([topicId, topicReport]) => {
                            const topicDetails = topicDetailsMap.get(topicId);
                            // @ts-ignore
                            const topicName = topicDetails?.topicName; // <-- this is still needed, because topicDetails can be undefined.
                            // @ts-ignore
                            const unit = topicDetails?.unit;

                            return (
                                <TableRow key={topicId}>
                                    <TableCell>{topicName}</TableCell>
                                    <TableCell>{unit}</TableCell>
                                    {/* ... (rest of the table cells) ... */}
                                </TableRow>
                            );
                        })}
                    </TableBody>
                </Table>
        </div>
    );
};

export default StructureReport;
```


