            <td style={tdStyle}>{totalPoints > 0 ? `${(docHieuPoints / totalPoints * 100).toFixed(2)}%` : '40.00%'}</td>
          </tr>
          <tr>
            <td style={tdStyle}><strong>2</strong></td>
