        mc: parseFloat(activeConfig.cauHoiTracNghiem.diem) || 0,
        tf: parseFloat(activeConfig.cauHoiDungSai.diem) || 0,
        sa: parseFloat(activeConfig.cauHoiTraLoiNgan.diem) || 0,
