                <CardContent className="space-y-4">
                    <div>
                        <Label className="flex items-center gap-2 mb-2"><Sliders size={16} className="text-indigo-500"/>Tỉ lệ % điểm</Label>
                        <div className="grid grid-cols-2 gap-4">
