                <Table>
                    <TableHeader><TableRow><TableHead>Mức độ</TableHead><TableHead>Số câu</TableHead><TableHead>Tổng điểm</TableHead><TableHead>Tỉ lệ %</TableHead></TableRow></TableHeader>
                    <TableBody>
                        {levels.map(level => (
                            <TableRow key={level.key}>
