            html += renderQuestions(questionsByType.multipleChoice);
        }

        if (tfCount > 0) {
            html += `<p><strong>II. Trắc nghiệm Đúng/Sai (Tổng số câu: ${tfCount}, Điểm: ${tfPoints.toFixed(2)})</strong></p>`;
