                                shortAnswer: questionDistributionSchema,
                                essay: questionDistributionSchema,
                            },
                            required: ['id', 'topicName', 'unit', 'requirements', 'multipleChoice', 'trueFalse', 'shortAnswer', 'essay']
                        }
                    };

                    const questionsSchema = {
                        type: Type.ARRAY,
