};

const StructureSummaryTable: React.FC<{ stats: any, isNguVan: boolean }> = ({ stats, isNguVan }) => {
    const rows = isNguVan
        ? [{ key: 'docHieu', label: 'Đọc hiểu' }, { key: 'viet', label: 'Viết' }]
