                <Table>
                    <TableHeader><TableRow><TableHead>{isNguVan ? 'Phần' : 'Loại câu hỏi'}</TableHead><TableHead>Số câu</TableHead><TableHead>Tổng điểm</TableHead></TableRow></TableHeader>
                    <TableBody>
                        {rows.map(row => (stats[row.key] && stats[row.key].count > 0) ? (
