const TnTlDistributionTable: React.FC<{ stats: any; totalPoints: number; isNguVan: boolean }> = ({ stats, totalPoints, isNguVan }) => {
    const tnLabel = isNguVan ? 'Đọc hiểu' : 'Trắc nghiệm (TN)';
    const tlLabel = isNguVan ? 'Viết' : 'Tự luận (TL)';

    return (
        <Card>
