import React, { useState } from "react";
import {
  FileText,
  Copy,
  FileSpreadsheet,
  FileType,
  Printer,
  ChevronLeft,
  ChevronRight,
  Download,
} from "../icons";
import { Button } from "../ui/Button";
import { useTheme } from "../../hooks/useTheme";
import { useToast } from "../../hooks/useToast";
import { useSettings } from "../../hooks/useSettings";
import { useI18n } from "../../hooks/useI18n";

export default function RightSidebar() {
  const [open, setOpen] = useState(true);
  const { theme } = useTheme();
  const { addToast } = useToast();
  const { settings } = useSettings();
  const { t } = useI18n();

  const sanitize = (str: string) => {
    if (!str) return '';
    return str
      .replace(/\s+/g, '_') // replace spaces with underscores
      .replace(/[\\/:"*?<>|]/g, '-'); // replace invalid filename characters
  };

  const generateFilename = (descriptor: string) => {
    const { subject, grade, examType } = settings;

    const parts = [
        sanitize(subject || 'MonHoc'),
        sanitize(grade ? `Lop${grade}` : 'Lop'),
        sanitize(examType || 'BaiKiemTra'),
        sanitize(descriptor)
    ].filter(Boolean);

    return parts.join('_');
  };

  const getActiveContentElement = (): HTMLElement | null => {
    return document.getElementById('printable-content');
  };

  const downloadFile = (filename: string, content: string, mimeType: string) => {
    const isTextBased = mimeType.startsWith('text/') || mimeType.includes('csv');
    const contentWithBOM = isTextBased ? '\uFEFF' + content : content;
    const blob = new Blob([contentWithBOM], { type: `${mimeType};charset=utf-8;` });

    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(link.href);
  };

  const htmlTableToCsv = (tableEl: HTMLTableElement): string | null => {
    if (!tableEl) return null;
    const rows = Array.from(tableEl.querySelectorAll('tr'));
    return rows.map(row => {
      const cells = Array.from(row.querySelectorAll<HTMLElement>('th, td'));
      return cells.map(cell => {
        let text = cell.innerText.replace(/"/g, '""').replace(/\n/g, " ");
        if (text.includes(',')) {
          text = `"${text}"`;
        }
        return text;
      }).join(',');
    }).join('\n');
  };

  const handleNotImplemented = () => {
    addToast(t('rightSidebar.notImplemented', "Tính năng này đang được phát triển."));
  };

  const handlePrint = () => {
    window.print();
  };

  const handleCopy = () => {
    const contentEl = getActiveContentElement();
    const previewEl = contentEl?.querySelector('[data-doc-type]');
    const exportContentEl = previewEl || contentEl;

    if (exportContentEl) {
      // FIX: Cast exportContentEl to HTMLElement to access the 'innerText' property.
      navigator.clipboard.writeText((exportContentEl as HTMLElement).innerText).then(() => {
        addToast(t('toasts.copiedToClipboard', "Đã sao chép nội dung vào clipboard."));
      }).catch(err => {
        addToast(t('toasts.copyError', "Lỗi: Không thể sao chép nội dung."));
        console.error('Could not copy text: ', err);
      });
    } else {
      addToast(t('toasts.noContentToCopy', "Không tìm thấy nội dung để sao chép."));
    }
  };

  const handleExportDocx = () => {
    const contentEl = getActiveContentElement();
    if (contentEl) {
        const previewEl = contentEl.querySelector('[data-doc-type]');
        const descriptor = previewEl?.getAttribute('data-doc-type') || 'TaiLieu';

        // Basic CSS for better Word rendering.
        const styles = `
            body { font-family: 'Times New Roman', Times, serif; font-size: 13pt; }
            table { border-collapse: collapse; width: 100%; margin-bottom: 1em; }
            th, td { border: 1px solid black; padding: 5px; text-align: left; vertical-align: top; }
            th { font-weight: bold; text-align: center; }
            p, li, div { margin: 0; padding: 0; line-height: 1.5; }
            h1, h2, h3, h4, h5, h6 { margin: 12pt 0 3pt 0; font-weight: bold; page-break-after: avoid; }
            strong { font-weight: bold; }
            em, i { font-style: italic; }
        `;

        const header = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
            <head>
                <meta charset='utf-8'>
                <title>Export HTML to Word</title>
                <style>${styles}</style>
            </head>
            <body>`;

        const footer = "</body></html>";
        const sourceHTML = header + (previewEl?.innerHTML || contentEl.innerHTML) + footer;
        const filename = generateFilename(descriptor);

        // CRITICAL FIX: Save as .doc, not .docx, to match the MIME type and improve compatibility.
        // Word is much better at interpreting HTML content when the file is a .doc.
        downloadFile(`${filename}.doc`, sourceHTML, 'application/msword');
        addToast(t('toasts.exportingFile', 'Đang xuất file {fileType}...', { fileType: '.DOC' }));
    } else {
        addToast(t('toasts.exportError', "Không tìm thấy nội dung để xuất file."));
    }
  };

  const handleExportXlsx = () => {
    const contentEl = getActiveContentElement();
    const previewEl = contentEl?.querySelector('[data-doc-type*="MaTrận"], [data-doc-type*="BaoCao"]');
    const tableEl = previewEl?.querySelector('table') || contentEl?.querySelector('table');

    if (tableEl) {
        const csvContent = htmlTableToCsv(tableEl);
        if (csvContent) {
            let descriptor = 'BangDuLieu';
            if (previewEl) {
                descriptor = previewEl.getAttribute('data-doc-type') || descriptor;
            }
            const filename = generateFilename(descriptor);
            // Save as CSV, which Excel can open perfectly. This is more robust than pretending it's an XLS file.
            downloadFile(`${filename}.csv`, csvContent, 'text/csv');
            addToast(t('toasts.exportingFile', 'Đang xuất file {fileType}...', { fileType: '.CSV' }));
        } else {
            addToast(t('toasts.exportTableToCsvError', "Không thể chuyển đổi bảng thành CSV."));
        }
    } else {
        addToast(t('toasts.exportNoTableError', "Không tìm thấy ma trận/bảng để xuất file."));
    }
  };

  const handleExport = (format: 'md' | 'txt' | 'rtf' | 'csv') => {
      const contentEl = getActiveContentElement();
      if (!contentEl) {
          addToast(t('toasts.exportError', "Không tìm thấy nội dung để xuất file."));
          return;
      }

      const previewEl = contentEl.querySelector('[data-doc-type]');
      const exportContentEl = previewEl || contentEl;
      const descriptor = previewEl?.getAttribute('data-doc-type') || 'NoiDung';

      // FIX: Cast exportContentEl to HTMLElement to access the 'innerText' property.
      let content = (exportContentEl as HTMLElement).innerText;
      let mimeType = 'text/plain';
      let fileDescriptor = descriptor;

      switch (format) {
          case 'md':
              mimeType = 'text/markdown';
              break;
          case 'txt':
              break;
          case 'rtf':
              // FIX: Cast exportContentEl to HTMLElement to access the 'innerText' property.
              content = `{\\rtf1\\ansi\\deff0 {\\fonttbl{\\f0 Times New Roman;}} \\fs24 ${(exportContentEl as HTMLElement).innerText.replace(/\n/g, '\\par ')}}`;
              mimeType = 'application/rtf';
              break;
          case 'csv':
              const tableEl = exportContentEl.querySelector('table');
              if (tableEl) {
                  const csvContent = htmlTableToCsv(tableEl);
                  if (csvContent) {
                      content = csvContent;
                      mimeType = 'text/csv';
                      fileDescriptor = `Bang_${descriptor}`;
                  } else {
                      addToast(t('toasts.exportTableToCsvError', "Không thể chuyển đổi bảng thành CSV."));
                      return;
                  }
              } else {
                  addToast(t('toasts.exportNoTableError', "Không tìm thấy bảng để xuất CSV."));
                  return;
              }
              break;
      }
      const filenameBase = generateFilename(fileDescriptor);
      downloadFile(`${filenameBase}.${format}`, content, mimeType);
      addToast(t('toasts.exportingFile', 'Đang xuất file {fileType}...', { fileType: `.${format.toUpperCase()}` }));
  };

  const handleOneClickExport = async () => {
    addToast(t('toasts.oneClickExportStarted', "Bắt đầu quá trình xuất đa định dạng..."));

    const contentEl = getActiveContentElement();
    if (!contentEl) {
        addToast(t('toasts.exportError', "Không tìm thấy nội dung để xuất file."));
        return;
    }

    // A small delay to allow the first toast to show
    await new Promise(resolve => setTimeout(resolve, 300));

    // 1. Export as DOC
    handleExportDocx();
    await new Promise(resolve => setTimeout(resolve, 800)); // Delay between downloads

    // 2. Export as TXT
    handleExport('txt');
    await new Promise(resolve => setTimeout(resolve, 800));

    // 3. Export as CSV (if applicable)
    const previewEl = contentEl.querySelector('[data-doc-type]');
    const tableEl = previewEl?.querySelector('table') || contentEl?.querySelector('table');
    if (tableEl) {
        handleExportXlsx();
        await new Promise(resolve => setTimeout(resolve, 800));
    }

    // 4. Trigger Print to PDF
    addToast(t('toasts.oneClickExportPdf', "Mở hộp thoại In để lưu dưới dạng PDF."));
    await new Promise(resolve => setTimeout(resolve, 500));
    handlePrint();
  };


  return (
      <aside
        className={`relative shadow-lg z-30 flex flex-col justify-between transition-all duration-300 ease-in-out no-print
          ${open ? "w-72" : "w-12"} 
          ${theme === "dark" ? "bg-slate-900 text-slate-100 border-l border-slate-800" : "bg-white text-slate-800 border-l border-slate-200"}`}
      >
        <button
          onClick={() => setOpen(!open)}
          className="absolute -left-4 top-1/2 transform -translate-y-1/2 bg-indigo-600 text-white p-1 rounded-full shadow hover:bg-indigo-700 transition"
          title={open ? "Thu gọn" : "Mở rộng"}
        >
          {open ? <ChevronRight size={18} /> : <ChevronLeft size={18} />}
        </button>

        <div className={`p-4 space-y-5 overflow-y-auto transition-opacity duration-300 ${open ? 'opacity-100' : 'opacity-0'}`}>
          {open && (
            <>
              <h2 className="text-lg font-semibold mb-2 border-b border-slate-300 dark:border-slate-700 pb-2">
                🧾 {t('rightSidebar.title', 'Thanh thông tin & Tác vụ')}
              </h2>

               <Button onClick={handleOneClickExport} className="w-full flex items-center gap-2 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-700 hover:to-purple-700 text-white shadow-lg transform hover:scale-105 transition-transform">
                  <Download size={18} /> {t('rightSidebar.oneClickExport', 'One-click Export')}
                </Button>

              <div className="space-y-3">
                <div className="border rounded-xl p-3 bg-slate-50 dark:bg-slate-800/50">
                  <p className="font-medium mb-2 text-sm">🖨️ {t('rightSidebar.print', 'In & Xuất PDF')}</p>
                  <Button onClick={handlePrint} className="w-full flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white">
                    <Printer size={18} /> {t('rightSidebar.printButton', 'In đề thi & đáp án')}
                  </Button>
                </div>

                <div className="border rounded-xl p-3 bg-slate-50 dark:bg-slate-800/50">
                  <p className="font-medium mb-2 text-sm">📄 {t('rightSidebar.wordExport', 'Xuất file Word')}</p>
                  <Button onClick={handleExportDocx} className="w-full flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white">
                    <FileText size={18} /> {t('rightSidebar.wordExportButton', 'Xuất .DOC')}
                  </Button>
                </div>

                <div className="border rounded-xl p-3 bg-slate-50 dark:bg-slate-800/50">
                  <p className="font-medium mb-2 text-sm">📊 {t('rightSidebar.matrixExport', 'Xuất ma trận')}</p>
                  <Button onClick={handleExportXlsx} className="w-full flex items-center gap-2 bg-green-600 hover:bg-green-700 text-white">
                    <FileSpreadsheet size={18} /> {t('rightSidebar.matrixExportButton', 'Xuất .CSV (Excel)')}
                  </Button>
                </div>

                 <div className="border rounded-xl p-3 bg-slate-50 dark:bg-slate-800/50">
                  <p className="font-medium mb-2 text-sm">📤 {t('rightSidebar.lmsExport', 'Xuất sang LMS')}</p>
                  <div className="flex flex-wrap gap-2">
                    <Button onClick={handleNotImplemented} size="sm" variant="outline" className="flex-1">Moodle</Button>
                    <Button onClick={handleNotImplemented} size="sm" variant="outline" className="flex-1">G-Classroom</Button>
                    <Button onClick={handleNotImplemented} size="sm" variant="outline" className="flex-1">MS Teams</Button>
                  </div>
                </div>

                <div className="border rounded-xl p-3 bg-slate-50 dark:bg-slate-800/50">
                  <p className="font-medium mb-2 text-sm">📋 {t('rightSidebar.copy', 'Sao chép nội dung')}</p>
                  <Button onClick={handleCopy} className="w-full flex items-center gap-2 bg-amber-500 hover:bg-amber-600 text-white">
                    <Copy size={18} /> {t('rightSidebar.copyButton', 'Sao chép toàn bộ')}
                  </Button>
                </div>

                <div className="border rounded-xl p-3 bg-slate-50 dark:bg-slate-800/50">
                  <p className="font-medium mb-2 text-sm">🧩 {t('rightSidebar.otherFormats', 'Định dạng khác')}</p>
                  <div className="flex flex-wrap gap-2">
                    <Button onClick={() => handleExport('md')} size="sm" variant="outline" className="flex items-center gap-2"> <FileType size={16} /> .MD </Button>
                    <Button onClick={() => handleExport('txt')} size="sm" variant="outline" className="flex items-center gap-2"> <FileType size={16} /> .TXT </Button>
                    <Button onClick={() => handleExport('rtf')} size="sm" variant="outline" className="flex items-center gap-2"> <FileType size={16} /> .RTF </Button>
                    <Button onClick={() => handleExport('csv')} size="sm" variant="outline" className="flex items-center gap-2"> <FileType size={16} /> .CSV </Button>
                  </div>
                </div>
              </div>
            </>
          )}
        </div>

        {open && (
          <div className="p-3 border-t border-slate-200 dark:border-slate-700 text-center text-xs opacity-70">
            © 2025 ExamGen Ultra 4.2
          </div>
        )}
      </aside>
  );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/Card';
import { Input } from '../ui/Input';
import { Label } from '../ui/Label';
import { Button } from '../ui/Button';
import { Loader2, User as UserIcon, Eye, EyeOff } from '../icons';
import { User } from '../../types';
import { useI18n } from '../../hooks/useI18n';

interface LoginScreenProps {
  onLoginSuccess: (user: User, rememberMe: boolean) => void;
  users: User[];
}

const LAST_LOGIN_USERNAME_KEY = 'examgen_last_login_username';
const ATTEMPTS_STORAGE_KEY = 'examgen_login_attempts';
const MAX_ATTEMPTS = 5;
const LOCKOUT_DURATION_MINUTES = 5;


const LoginScreen: React.FC<LoginScreenProps> = ({ onLoginSuccess, users }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null);
  const [foundUser, setFoundUser] = useState<User | null>(null);
  const { t } = useI18n();

  useEffect(() => {
    const lastUsername = localStorage.getItem(LAST_LOGIN_USERNAME_KEY);
    if (lastUsername) {
        setUsername(lastUsername);
    }
  }, []);

  useEffect(() => {
    const normalizedUsername = username.toLowerCase();
    const user = users.find(u => u.username.toLowerCase() === normalizedUsername);
    setFoundUser(user || null);

    if (user) {
      setAvatarUrl(user.avatar);
    } else {
      setAvatarUrl(null);
    }
  }, [username, users]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    // Simulate an API call with detailed validation
    setTimeout(() => {
      const now = Date.now();
      let attemptsData: { [key: string]: { count: number; lockedUntil: number } } = {};
      try {
        const savedAttempts = sessionStorage.getItem(ATTEMPTS_STORAGE_KEY);
        if (savedAttempts) attemptsData = JSON.parse(savedAttempts);
      } catch (e) {}

      const userAttempts = attemptsData[username.toLowerCase()] || { count: 0, lockedUntil: 0 };

      if (userAttempts.lockedUntil > now) {
        setError(t('login.error.locked', `Tài khoản bị tạm khóa. Vui lòng thử lại sau ${Math.ceil((userAttempts.lockedUntil - now) / 1000 / 60)} phút.`, { minutes: Math.ceil((userAttempts.lockedUntil - now) / 1000 / 60) }));
        setIsLoading(false);
        return;
      }

      if (!foundUser) {
        setError(t('login.error.notFound', 'Tài khoản này chưa được quản trị viên tạo. Vui lòng liên hệ Admin để được cấp quyền đăng nhập.'));
        setIsLoading(false);
        return;
      }

      if (foundUser.status === 'Tạm khóa') {
        setError(t('login.error.disabled', 'Tài khoản của bạn đã bị vô hiệu hóa. Vui lòng liên hệ Admin.'));
        setIsLoading(false);
        return;
      }

      if (password !== foundUser.password) {
        const newCount = userAttempts.count + 1;
        if (newCount >= MAX_ATTEMPTS) {
          attemptsData[username.toLowerCase()] = { count: newCount, lockedUntil: now + LOCKOUT_DURATION_MINUTES * 60 * 1000 };
          setError(t('login.error.tooManyAttempts', 'Bạn đã nhập sai quá {maxAttempts} lần. Tài khoản bị tạm khóa trong {minutes} phút.', { maxAttempts: MAX_ATTEMPTS, minutes: LOCKOUT_DURATION_MINUTES }));
        } else {
          attemptsData[username.toLowerCase()] = { count: newCount, lockedUntil: 0 };
          setError(t('login.error.wrongCredentials', 'Tên đăng nhập hoặc mật khẩu không chính xác.'));
        }
        sessionStorage.setItem(ATTEMPTS_STORAGE_KEY, JSON.stringify(attemptsData));
        setIsLoading(false);
        return;
      }

      // Success: Clear attempts and proceed to login
      delete attemptsData[username.toLowerCase()];
      sessionStorage.setItem(ATTEMPTS_STORAGE_KEY, JSON.stringify(attemptsData));
      onLoginSuccess(foundUser, false);
    }, 1000);
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-100 dark:bg-gray-950">
       <div className="absolute inset-0 bg-gradient-to-br from-blue-100 via-white to-purple-100 dark:from-gray-900 dark:via-gray-950 dark:to-indigo-950 -z-10"></div>
      <Card className="w-full max-w-sm shadow-2xl border-none animate-in fade-in-0 zoom-in-95">
        <CardHeader className="text-center">
          <div className="relative mx-auto w-24 h-24 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center text-gray-400 dark:text-gray-500 shadow-lg mb-4 overflow-hidden">
            {avatarUrl ? (
                <img key={avatarUrl} src={avatarUrl} alt="User Avatar" className="w-full h-full object-cover animate-in fade-in-0 duration-500" />
            ) : (
                <UserIcon size={48} />
            )}
          </div>
          <CardTitle className="text-2xl font-bold text-gray-800 dark:text-gray-100">{t('login.title', 'Đăng nhập ExamGen Ultra 4.2')}</CardTitle>
          <p className="text-sm text-gray-500 dark:text-gray-400">{t('login.welcome', 'Chào mừng bạn trở lại!')}</p>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleLogin} className="space-y-4">
            <div className="space-y-1.5">
              <Label htmlFor="username">{t('login.usernameLabel', 'Tài khoản')}</Label>
              <Input
                id="username"
                autoComplete="username"
                placeholder={t('login.usernamePlaceholder', 'Tên đăng nhập')}
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                required
                disabled={isLoading}
              />
            </div>
            <div className="space-y-1.5 relative">
              <Label htmlFor="password">{t('login.passwordLabel', 'Mật khẩu')}</Label>
              <Input
                id="password"
                type={showPassword ? 'text' : 'password'}
                placeholder={t('login.passwordPlaceholder', '••••••••')}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                disabled={isLoading}
                className="pr-10"
              />
               <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-2 top-8 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                  {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
               </button>
            </div>

            {error && <p className="text-sm text-red-500 text-center p-2 bg-red-50 dark:bg-red-900/20 rounded-md">{error}</p>}

            {foundUser && foundUser.role === 'Giáo viên' && foundUser.usageLimit != null && (
                <div 
                    className="text-xs text-center text-gray-500 dark:text-gray-400 p-2 bg-gray-50 dark:bg-gray-800 rounded-md border border-gray-200 dark:border-gray-700"
                    dangerouslySetInnerHTML={{ __html: t('login.trial.remaining', 'Số lần đăng nhập dùng thử còn lại: <strong>{remaining}</strong> / {limit}', { remaining: Math.max(0, foundUser.usageLimit - (foundUser.usageCount || 0)), limit: foundUser.usageLimit }) }}
                />
            )}

            <div className="flex items-center justify-end pt-2">
              <a href="#" onClick={(e) => e.preventDefault()} className="text-sm text-blue-600 hover:underline dark:text-blue-400">
                {t('login.forgotPassword', 'Quên mật khẩu?')}
              </a>
            </div>
            <Button type="submit" className="w-full" disabled={isLoading}>
              {isLoading ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  {t('login.loggingInButton', 'Đang xử lý...')}
                </>
              ) : (
                t('login.loginButton', 'Đăng nhập')
              )}
            </Button>
          </form>
           <p className="mt-6 text-center text-xs text-gray-500 dark:text-gray-400">
            {t('login.footer', 'ExamGen Ultra 4.2 – Nền tảng ra đề thông minh dành cho giáo viên Việt Nam.')}
          </p>
        </CardContent>
      </Card>
    </div>
  );
};

export default LoginScreen;

import React, { useState, useMemo, useEffect, useRef } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "../ui/Card";
import { Input } from "../ui/Input";
import { Label } from "../ui/Label";
import { Button } from "../ui/Button";
import { Select, SelectTrigger, SelectContent, SelectItem, SelectValue } from "../ui/Select";
import { Checkbox } from "../ui/Checkbox";
import { Table, TableHeader, TableBody, TableRow, TableHead, TableCell } from "../ui/Table";
import { Badge } from "../ui/Badge";
import { Users, Search, Plus, MoreHorizontal, ChevronLeft, ChevronRight, Edit, Trash2, Lock, Unlock, KeyRound, XCircle, Upload, Loader2, FolderCog, Zap, User as UserIcon, Info, Shield, BookOpen } from "../icons";
import { useToast } from "../../hooks/useToast";
import { User } from "../../types";
import { PROFESSIONAL_GROUPS, SCHOOLS_BY_PROVINCE } from "../../constants";
import { SelectWithOther } from '../ui/SelectWithOther';

const DEFAULT_ITEMS_PER_PAGE = 10;
const FILTERS_STORAGE_KEY = 'form_user_management_filters';

interface UserManagementWorkspaceProps {
    users: User[];
    setUsers: (users: User[] | ((prevUsers: User[]) => User[])) => void;
    currentUser: User;
    setCurrentUser: React.Dispatch<React.SetStateAction<User | null>>;
}

export default function UserManagementWorkspace({ users, setUsers, currentUser, setCurrentUser }: UserManagementWorkspaceProps) {
    const { addToast } = useToast();
    const [selectedIds, setSelectedIds] = useState<Set<number>>(new Set());
    const [openActionMenuId, setOpenActionMenuId] = useState<number | null>(null);
    const [modalState, setModalState] = useState<{ mode: 'add' | 'edit' | null; user?: User }>({ mode: null });
    const [itemsToDelete, setItemsToDelete] = useState<{ users: User[], ids: number[] } | null>(null);
    const [userToResetPassword, setUserToResetPassword] = useState<User | null>(null);
    const [isBulkRoleModalOpen, setIsBulkRoleModalOpen] = useState(false);
    const actionMenuRef = useRef<HTMLDivElement>(null);
    const [sortConfig, setSortConfig] = useState<{ key: keyof User; direction: 'ascending' | 'descending' } | null>(null);
    const [recentlyModifiedId, setRecentlyModifiedId] = useState<number | null>(null);

    const allSchools = useMemo(() => {
        const schools = Object.values(SCHOOLS_BY_PROVINCE).flat();
        return [...new Set(schools)].sort((a, b) => a.localeCompare(b, 'vi'));
    }, []);

    const allProfessionalGroups = useMemo(() => {
        const allGroups = Object.values(PROFESSIONAL_GROUPS).flat();
        return [...new Set(allGroups)].sort((a, b) => a.localeCompare(b, 'vi'));
    }, []);

    const [searchInputValue, setSearchInputValue] = useState(() => {
        try {
            const saved = localStorage.getItem(FILTERS_STORAGE_KEY);
            return saved ? JSON.parse(saved).searchQuery : '';
        } catch (e) { return ''; }
    });

    const [filters, setFilters] = useState(() => {
        try {
            const saved = localStorage.getItem(FILTERS_STORAGE_KEY);
            const parsed = saved ? JSON.parse(saved) : {};
            return {
                searchQuery: parsed.searchQuery || '',
                roleFilter: parsed.roleFilter || 'all',
                statusFilter: parsed.statusFilter || 'all'
            };
        } catch (e) {
            return { searchQuery: '', roleFilter: 'all', statusFilter: 'all' };
        }
    });

    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage, setItemsPerPage] = useState(DEFAULT_ITEMS_PER_PAGE);

    useEffect(() => {
        if (recentlyModifiedId) {
            const timer = setTimeout(() => {
                setRecentlyModifiedId(null);
            }, 3000); // Highlight for 3 seconds
            return () => clearTimeout(timer);
        }
    }, [recentlyModifiedId]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (actionMenuRef.current && !actionMenuRef.current.contains(event.target as Node)) {
                setOpenActionMenuId(null);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    useEffect(() => {
        localStorage.setItem(FILTERS_STORAGE_KEY, JSON.stringify(filters));
    }, [filters]);

    const handleSearch = () => {
        setFilters(prev => ({...prev, searchQuery: searchInputValue}));
        setCurrentPage(1);
    }

    const handleClearSearch = () => {
        setSearchInputValue('');
        setFilters(prev => ({...prev, searchQuery: ''}));
        setCurrentPage(1);
    }

    const requestSort = (key: keyof User) => {
        if (sortConfig && sortConfig.key === key) {
            if (sortConfig.direction === 'ascending') {
                setSortConfig({ key, direction: 'descending' });
            } else {
                setSortConfig(null); // Clear sort on third click
            }
        } else {
            setSortConfig({ key, direction: 'ascending' });
        }
        setCurrentPage(1); // Reset to first page on sort
    };

    const handleSelectFilterChange = (filterName: 'roleFilter' | 'statusFilter', value: string) => {
        setFilters((prev) => ({ ...prev, [filterName]: value }));
        setCurrentPage(1);
    };

    const filteredUsers = useMemo(() => {
        return users.filter(user => {
            const searchLower = filters.searchQuery.toLowerCase();
            const matchesSearch = user.name.toLowerCase().includes(searchLower) || user.email.toLowerCase().includes(searchLower) || user.username.toLowerCase().includes(searchLower);
            const matchesRole = filters.roleFilter === 'all' || user.role === filters.roleFilter;
            const matchesStatus = filters.statusFilter === 'all' || user.status === filters.statusFilter;
            return matchesSearch && matchesRole && matchesStatus;
        });
    }, [filters, users]);

    const sortedUsers = useMemo(() => {
        const sortableUsers = [...filteredUsers];
        sortableUsers.sort((a, b) => {
            if (a.role === 'Quản trị hệ thống' && b.role !== 'Quản trị hệ thống') return -1;
            if (a.role !== 'Quản trị hệ thống' && b.role === 'Quản trị hệ thống') return 1;
            if (sortConfig) {
                const aValue = a[sortConfig.key];
                const bValue = b[sortConfig.key];
                if (typeof aValue === 'string' && typeof bValue === 'string') {
                    const comparison = aValue.localeCompare(bValue, 'vi');
                    if (comparison !== 0) return sortConfig.direction === 'ascending' ? comparison : -comparison;
                }
                if (aValue < bValue) return sortConfig.direction === 'ascending' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'ascending' ? 1 : -1;
            }
            return a.id - b.id;
        });
        return sortableUsers;
    }, [filteredUsers, sortConfig]);

    const totalPages = Math.ceil(sortedUsers.length / itemsPerPage);

    useEffect(() => {
        if (currentPage > totalPages && totalPages > 0) {
            setCurrentPage(totalPages);
        }
    }, [currentPage, totalPages]);

    const paginatedUsers = sortedUsers.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

    const handlePageChange = (newPage: number) => {
        if (newPage >= 1 && newPage <= totalPages) setCurrentPage(newPage);
    };

    const handleSelect = (userId: number, checked: boolean) => {
        const newSet = new Set(selectedIds);
        if (checked) newSet.add(userId);
        else newSet.delete(userId);
        setSelectedIds(newSet);
    };

    const handleSelectAll = (checked: boolean) => {
        if (checked) setSelectedIds(new Set(paginatedUsers.map(u => u.id)));
        else setSelectedIds(new Set());
    };

    const handleSaveUser = async (userData: Partial<User>, id?: number) => {
        await new Promise(resolve => setTimeout(resolve, 700)); // Simulate API call

        const typedUserData = {
            ...userData,
            role: userData.role as User['role'],
            status: userData.status as User['status'],
        };

        if (id) { // Edit mode
            if (id === currentUser.id) {
                setCurrentUser(prevUser => {
                    if (!prevUser) return null;
                    return { ...prevUser, ...typedUserData };
                });
            } else {
                setUsers(prevUsers => prevUsers.map(u => u.id === id ? { ...u, ...typedUserData } : u));
            }
            setRecentlyModifiedId(id);
            addToast(`Đã cập nhật người dùng ${typedUserData.name}.`);
        } else { // Add mode
            const newId = users.length > 0 ? Math.max(...users.map(u => u.id)) + 1 : 1;
            const newUser: User = {
                id: newId,
                name: typedUserData.name || 'Người dùng mới',
                username: typedUserData.username || `user${Date.now()}`,
                email: typedUserData.email || '',
                password: typedUserData.password,
                role: typedUserData.role || 'Giáo viên',
                school: typedUserData.school || '',
                profGroup: typedUserData.profGroup || '',
                status: 'Hoạt động',
                lastLogin: '',
                avatar: typedUserData.avatar || `https://i.pravatar.cc/150?u=${newId}`,
                usageCount: 0,
                tokenUsage: 0,
                usageLimit: typedUserData.usageLimit || 5,
            };
            setUsers(prevUsers => [newUser, ...prevUsers]);
            setRecentlyModifiedId(newId);
            addToast(`Đã thêm người dùng ${newUser.name}.`);
        }
        setModalState({ mode: null });
    };

    const handleToggleStatus = (user: User) => {
        if (user.id === currentUser.id) {
            addToast("Lỗi: Bạn không thể tự khóa tài khoản của mình.");
            setOpenActionMenuId(null);
            return;
        }
        const newStatus: User['status'] = user.status === 'Hoạt động' ? 'Tạm khóa' : 'Hoạt động';
        const updatedUser = { ...user, status: newStatus };

        setUsers(prevUsers => prevUsers.map(u => u.id === user.id ? updatedUser : u));
        setRecentlyModifiedId(user.id);

        addToast(`Đã ${newStatus === 'Hoạt động' ? 'kích hoạt' : 'tạm khóa'} tài khoản ${user.name}.`);
        setOpenActionMenuId(null);
    };

    const handleToggleRole = (user: User) => {
        if (user.id === currentUser.id) {
            addToast("Lỗi: Bạn không thể tự thay đổi vai trò của mình.");
            setOpenActionMenuId(null);
            return;
        }

        const adminUsers = users.filter(u => u.role === 'Quản trị hệ thống');
        if (user.role === 'Quản trị hệ thống' && adminUsers.length === 1) {
            addToast("Lỗi: Không thể thay đổi vai trò của quản trị viên cuối cùng.");
            setOpenActionMenuId(null);
            return;
        }

        const newRole: User['role'] = user.role === 'Quản trị hệ thống' ? 'Giáo viên' : 'Quản trị hệ thống';
        const updatedUser = { ...user, role: newRole };

        setUsers(prevUsers => prevUsers.map(u => u.id === user.id ? updatedUser : u));
        setRecentlyModifiedId(user.id);

        addToast(`Đã đổi vai trò của ${user.name} thành ${newRole}.`);
        setOpenActionMenuId(null);
    };

    const handleDeleteRequest = (usersToDelete: User[]) => {
        if (usersToDelete.length === 0) return;

        if (usersToDelete.some(u => u.id === currentUser.id)) {
            addToast("Lỗi: Bạn không thể xóa tài khoản của chính mình.");
            return;
        }

        const adminUsers = users.filter(u => u.role === 'Quản trị hệ thống');
        const adminsToDelete = usersToDelete.filter(u => u.role === 'Quản trị hệ thống');
        if (adminUsers.length > 0 && adminUsers.length === adminsToDelete.length) {
            addToast("Lỗi: Không thể xóa quản trị viên cuối cùng của hệ thống.");
            return;
        }

        setItemsToDelete({ users: usersToDelete, ids: usersToDelete.map(u => u.id) });
    };

    const confirmDelete = () => {
        if (!itemsToDelete) return;

        setUsers(prevUsers => prevUsers.filter(u => !itemsToDelete.ids.includes(u.id)));
        addToast(`Đã xóa ${itemsToDelete.ids.length} người dùng.`);
        setItemsToDelete(null);
        setSelectedIds(new Set());
    };

    const handleConfirmResetPassword = (password: string) => {
        if (!userToResetPassword) return;
        console.log(`Password for user ${userToResetPassword.name} reset to: ${password}`);
        addToast(`Đã đặt lại mật khẩu cho ${userToResetPassword.name}.`);
        setUserToResetPassword(null);
    };

    const handleBulkRoleUpdate = (newRole: User['role']) => {
        setUsers(users => {
            const newUsers = users.map(user => {
                if (selectedIds.has(user.id)) {
                    const adminUsers = users.filter(u => u.role === 'Quản trị hệ thống');
                    if(user.role === 'Quản trị hệ thống' && newRole !== 'Quản trị hệ thống' && adminUsers.length === 1 && adminUsers[0].id === user.id) {
                         addToast(`Không thể thay đổi vai trò của quản trị viên cuối cùng: ${user.name}.`);
                         return user;
                    }
                    return { ...user, role: newRole };
                }
                return user;
            });

            const wasCurrentUserUpdated = selectedIds.has(currentUser.id);
            if (wasCurrentUserUpdated) {
                 addToast("Lỗi: Bạn không thể tự thay đổi vai trò của mình trong thao tác hàng loạt.");
                 return users; // Revert changes if current user was included
            }
            return newUsers;
        });

        addToast(`Đã cập nhật vai trò cho ${selectedIds.size} người dùng.`);
        setSelectedIds(new Set());
        setIsBulkRoleModalOpen(false);
    };

    const getRoleBadgeVariant = (role: User['role']) => (
        { 'Quản trị hệ thống': 'danger', 'Giáo viên': 'info' }[role] || 'default'
    ) as any;

    const getStatusBadgeVariant = (status: User['status']) => (status === 'Hoạt động' ? 'success' : 'warning');

    const isAllSelected = paginatedUsers.length > 0 && paginatedUsers.every(u => selectedIds.has(u.id));

    return (
        <>
            <Card className="shadow-lg border-none bg-white dark:bg-slate-900 h-full flex flex-col">
                <CardHeader className="flex flex-row items-start justify-between">
                    <div>
                        <CardTitle className="flex items-center gap-2 text-xl font-bold text-slate-800 dark:text-slate-100">
                            <Users className="w-6 h-6" /> Quản lý người dùng
                        </CardTitle>
                        {selectedIds.size > 0 && (
                            <div className="mt-2 flex items-center gap-2">
                                <span className="text-sm text-slate-500">{selectedIds.size} mục đã chọn</span>
                                <Button variant="outline" size="sm" className="text-indigo-600 dark:text-indigo-400 border-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20" onClick={() => setIsBulkRoleModalOpen(true)}>
                                    <Users className="w-4 h-4 mr-2" /> Thay đổi vai trò
                                </Button>
                                <Button variant="ghost" size="sm" className="text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20" onClick={() => handleDeleteRequest(users.filter(u => selectedIds.has(u.id)))}>
                                    <Trash2 className="w-4 h-4 mr-2" /> Xóa mục đã chọn
                                </Button>
                            </div>
                        )}
                    </div>
                    <Button onClick={() => setModalState({ mode: 'add' })}>
                        <Plus className="w-4 h-4 mr-2" /> Thêm người dùng mới
                    </Button>
                </CardHeader>
                <CardContent className="flex-grow flex flex-col">
                    <div className="flex flex-col md:flex-row items-center gap-4 mb-4">
                        <div className="flex items-center gap-2 w-full md:flex-grow">
                            <div className="relative flex-grow">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                                <Input 
                                    placeholder="Tìm kiếm theo tên, email, tên đăng nhập..." 
                                    className="pl-10 pr-10"
                                    value={searchInputValue} 
                                    onChange={(e) => setSearchInputValue(e.target.value)}
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') {
                                            e.preventDefault();
                                            handleSearch();
                                        }
                                    }}
                                />
                                {searchInputValue && (
                                    <Button variant="ghost" size="sm" className="absolute right-1 top-1/2 -translate-y-1/2 p-1 h-auto rounded-full" onClick={handleClearSearch}>
                                        <XCircle className="w-5 h-5 text-slate-400"/>
                                    </Button>
                                )}
                            </div>
                            <Button onClick={handleSearch} className="flex-shrink-0">
                                <Search className="w-4 h-4 mr-2" />
                                Tìm kiếm
                            </Button>
                        </div>

                        <div className="flex gap-4 w-full md:w-auto flex-shrink-0">
                            <Select onValueChange={(value) => handleSelectFilterChange('roleFilter', value)} value={filters.roleFilter}>
                                <SelectTrigger className="w-full md:w-[180px]"><SelectValue placeholder="Lọc theo vai trò" /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="all">Tất cả vai trò</SelectItem>
                                    <SelectItem value="Quản trị hệ thống">Quản trị hệ thống</SelectItem>
                                    <SelectItem value="Giáo viên">Giáo viên</SelectItem>
                                </SelectContent>
                            </Select>
                            <Select onValueChange={(value) => handleSelectFilterChange('statusFilter', value)} value={filters.statusFilter}>
                                <SelectTrigger className="w-full md:w-[180px]"><SelectValue placeholder="Lọc theo trạng thái" /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="all">Tất cả trạng thái</SelectItem>
                                    <SelectItem value="Hoạt động">Hoạt động</SelectItem>
                                    <SelectItem value="Tạm khóa">Tạm khóa</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    <div className="flex-grow overflow-auto">
                        <Table>
                            <TableHeader>
                                <TableRow>
                                    <TableHead className="w-[50px]"><Checkbox checked={isAllSelected} onCheckedChange={(checked) => handleSelectAll(Boolean(checked))} /></TableHead>
                                    <TableHead>Họ và tên</TableHead>
                                    <TableHead>Tên đăng nhập</TableHead>
                                    <TableHead>Vai trò</TableHead>
                                    <TableHead>Thống kê sử dụng</TableHead>
                                    <TableHead>Trạng thái</TableHead>
                                    <TableHead className="text-right">Hành động</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {paginatedUsers.map(user => {
                                    const isCurrentUser = user.id === currentUser.id;
                                    return (
                                        <TableRow 
                                            key={user.id} 
                                            className={user.id === recentlyModifiedId ? 'bg-indigo-100 dark:bg-indigo-900/30' : ''}
                                        >
                                            <TableCell><Checkbox checked={selectedIds.has(user.id)} onCheckedChange={(checked) => handleSelect(user.id, Boolean(checked))} /></TableCell>
                                            <TableCell>
                                                <div className="flex items-center gap-3">
                                                    <img src={user.avatar} alt={user.name} className="w-10 h-10 rounded-full" />
                                                    <div>
                                                        <div className="font-medium text-slate-800 dark:text-slate-100">{user.name}</div>
                                                        <div className="text-sm text-slate-500 dark:text-slate-400">{user.email}</div>
                                                    </div>
                                                </div>
                                            </TableCell>
                                            <TableCell>
                                                <div className="text-sm font-medium text-slate-800 dark:text-slate-100">@{user.username}</div>
                                            </TableCell>
                                            <TableCell><Badge variant={getRoleBadgeVariant(user.role)}>{user.role}</Badge></TableCell>
                                            <TableCell>
                                                <div className="text-sm">
                                                    Logins: {user.usageCount}
                                                    {user.role !== 'Quản trị hệ thống' && user.usageLimit != null && ` / ${user.usageLimit}`}
                                                </div>
                                                <div className="text-xs text-slate-500 dark:text-slate-400">
                                                    Tokens: {(user.tokenUsage || 0).toLocaleString('vi-VN')}
                                                </div>
                                            </TableCell>
                                            <TableCell><Badge variant={getStatusBadgeVariant(user.status)}>{user.status}</Badge></TableCell>
                                            <TableCell className="text-right">
                                                <div className="relative inline-block text-left">
                                                    <Button variant="ghost" size="sm" onClick={() => setOpenActionMenuId(openActionMenuId === user.id ? null : user.id)}>
                                                        <MoreHorizontal className="w-5 h-5" />
                                                    </Button>
                                                    {openActionMenuId === user.id && (
                                                        <div ref={actionMenuRef} className="origin-top-right absolute right-0 mt-2 w-56 rounded-md shadow-lg bg-white dark:bg-slate-800 ring-1 ring-black ring-opacity-5 focus:outline-none z-10">
                                                            <div className="py-1">
                                                                <button onClick={() => { setModalState({ mode: 'edit', user }); setOpenActionMenuId(null); }} className="w-full text-left flex items-center gap-3 px-4 py-2 text-sm text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700"><Edit size={16}/> Chỉnh sửa</button>
                                                                <button onClick={() => handleToggleRole(user)} disabled={isCurrentUser} title={isCurrentUser ? "Không thể tự thay đổi vai trò" : ""} className="w-full text-left flex items-center gap-3 px-4 py-2 text-sm text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700 disabled:opacity-50 disabled:cursor-not-allowed"><Zap size={16}/> Đổi vai trò</button>
                                                                <button onClick={() => handleToggleStatus(user)} disabled={isCurrentUser} title={isCurrentUser ? "Không thể tự khóa tài khoản" : ""} className="w-full text-left flex items-center gap-3 px-4 py-2 text-sm text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700 disabled:opacity-50 disabled:cursor-not-allowed">
                                                                    {user.status === 'Hoạt động' ? <><Lock size={16}/> Tạm khóa</> : <><Unlock size={16}/> Kích hoạt</>}
                                                                </button>
                                                                <button onClick={() => { setUserToResetPassword(user); setOpenActionMenuId(null); }} className="w-full text-left flex items-center gap-3 px-4 py-2 text-sm text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700"><KeyRound size={16}/> Đặt lại mật khẩu</button>
                                                                <div className="border-t border-slate-100 dark:border-slate-700 my-1"></div>
                                                                <button onClick={() => { handleDeleteRequest([user]); setOpenActionMenuId(null); }} disabled={isCurrentUser} title={isCurrentUser ? "Không thể tự xóa tài khoản" : ""} className="w-full text-left flex items-center gap-3 px-4 py-2 text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 disabled:opacity-50 disabled:cursor-not-allowed"><Trash2 size={16}/> Xóa người dùng</button>
                                                            </div>
                                                        </div>
                                                    )}
                                                </div>
                                            </TableCell>
                                        </TableRow>
                                    );
                                })}
                            </TableBody>
                        </Table>
                    </div>

                    <div className="flex items-center justify-between mt-4 pt-4 border-t border-slate-200 dark:border-slate-800">
                        <div className="flex items-center gap-4 text-sm text-slate-600 dark:text-slate-400">
                           <span className="whitespace-nowrap">
                                Hiển thị {paginatedUsers.length > 0 ? (currentPage - 1) * itemsPerPage + 1 : 0}-{(currentPage - 1) * itemsPerPage + paginatedUsers.length} trên {sortedUsers.length}
                            </span>
                            <div className="hidden sm:flex items-center gap-2">
                                <Label htmlFor="rows-per-page" className="!mb-0 whitespace-nowrap">Hàng mỗi trang:</Label>
                                <Select onValueChange={(value) => { setItemsPerPage(Number(value)); setCurrentPage(1); }} defaultValue={String(DEFAULT_ITEMS_PER_PAGE)}>
                                    <SelectTrigger id="rows-per-page" className="w-20"><SelectValue /></SelectTrigger>
                                    <SelectContent>
                                        {[5, 10, 20, 50].map(val => <SelectItem key={val} value={String(val)}>{val}</SelectItem>)}
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            <Button variant="outline" size="sm" onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1}><ChevronLeft className="w-4 h-4" /> <span className="hidden sm:inline ml-1">Trước</span></Button>
                            <span className="text-sm font-medium">{currentPage} / {totalPages > 0 ? totalPages : 1}</span>
                            <Button variant="outline" size="sm" onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages}><span className="hidden sm:inline mr-1">Sau</span> <ChevronRight className="w-4 h-4" /></Button>
                        </div>
                    </div>
                </CardContent>
            </Card>

            {(modalState.mode === 'edit' || modalState.mode === 'add') && (
                <UserEditModal
                    isOpen={modalState.mode === 'edit' || modalState.mode === 'add'}
                    onClose={() => setModalState({ mode: null })}
                    onSave={handleSaveUser}
                    initialUser={modalState.mode === 'edit' ? modalState.user : undefined}
                    users={users}
                    allSchools={allSchools}
                    allProfessionalGroups={allProfessionalGroups}
                />
            )}
             {itemsToDelete && (
                <DeleteConfirmationModal 
                    isOpen={!!itemsToDelete}
                    onClose={() => setItemsToDelete(null)}
                    onConfirm={confirmDelete}
                    users={itemsToDelete.users}
                />
            )}
            {userToResetPassword && (
                <ResetPasswordModal
                    isOpen={!!userToResetPassword}
                    onClose={() => setUserToResetPassword(null)}
                    onConfirm={handleConfirmResetPassword}
                    user={userToResetPassword}
                />
            )}
             {isBulkRoleModalOpen && (
                <BulkRoleModal
                    isOpen={isBulkRoleModalOpen}
                    onClose={() => setIsBulkRoleModalOpen(false)}
                    onConfirm={handleBulkRoleUpdate}
                />
            )}
        </>
    );
}


