    const handleAutoSaveIntervalChange = (value: string) => {
        if (value === '' || /^\d+$/.test(value)) {
            const numValue = Number(value);
            if (value !== '' && (numValue < 1 || numValue > 60)) {
                setAutoSaveError("Hợp lệ: 1-60 phút.");
