                                    </div>
                                </div>
                            </div>
                            <div className="font-bold text-right mt-4">Tổng điểm toàn cấu trúc: {nguVanTotalScore}</div>
                            {parseFloat(nguVanTotalScore) !== scale && parseFloat(nguVanTotalScore) > 0 && (
