                                    <span>{t('examStructure.scoreMismatchWarning', 'Tổng điểm ({totalScore}) chưa khớp với thang điểm ({scale}).', { totalScore: nguVanTotalScore, scale: scale.toFixed(1) })}</span>
                                </div>
