                                        <TableCell><Input value={config.cauHoiTraLoiNgan.diem} onChange={e => handleQuestionStructureChange('cauHoiTraLoiNgan', 'diem', e.target.value)} /></TableCell>
                                        <TableCell>{calculateTotal(config.cauHoiTraLoiNgan)}</TableCell>
                                    </TableRow>
                                    <TableRow>
