     const manualStats = useMemo(() => {
        const { manual } = examSettings;
        let totalPoints = 0;
        const cognitive = {
            biet: { count: 0, points: 0 }, hieu: { count: 0, points: 0 },
            vd: { count: 0, points: 0 }, vdc: { count: 0, points: 0 }
        };
        const structure = isNguVan
