        return (docHieu + viet).toFixed(2);
    }, [config.nguVanTuDongDocHieuPart, config.nguVanTuDongVietPart]);

    const distTotal = (parseFloat(config.distTn) || 0) + (parseFloat(config.distTl) || 0);
